package server

import (
	_ "embed"
	"encoding/json"
	"net/http"
	"strings"
	"time"

	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
)

// crdsJSON is the read-only CustomResourceDefinitionList generated by
// hack/gen-openapi from the upstream Traefik CRD file. q8s does not store
// CRDs; it serves this fixed list so clients such as Terraform's
// kubernetes_manifest provider can discover the CRD schemas.
//
//go:embed crds.json
var crdsJSON []byte

const crdPath = "/apis/apiextensions.k8s.io/v1/customresourcedefinitions"

// crdListDocument is the wire shape of the embedded list. Items stay as
// generic maps so the full CRD schema is returned unchanged.
type crdListDocument struct {
	APIVersion string                   `json:"apiVersion"`
	Kind       string                   `json:"kind"`
	Metadata   map[string]interface{}   `json:"metadata"`
	Items      []map[string]interface{} `json:"items"`
}

// handleCRDs serves GET list and GET by name. All other methods return a
// MethodNotAllowed Status; CRDs are read-only in q8s.
func (s *Server) handleCRDs(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		s.respondStatus(w, http.StatusMethodNotAllowed, "MethodNotAllowed", "method not allowed")
		return
	}

	var doc crdListDocument
	if err := json.Unmarshal(crdsJSON, &doc); err != nil {
		s.respondStatus(w, http.StatusInternalServerError, "InternalError", "embedded CRD list: %s", err.Error())
		return
	}

	name := strings.Trim(strings.TrimPrefix(r.URL.Path, crdPath), "/")
	if name == "" {
		if doc.Metadata == nil {
			doc.Metadata = map[string]interface{}{}
		}
		doc.Metadata["resourceVersion"] = s.rv()
		if isTableRequest(r) {
			encodeTable(w, crdsToTable(doc.Items, s.rv()))
			return
		}
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(doc)
		return
	}

	for _, item := range doc.Items {
		if crdMetadata(item).Name != name {
			continue
		}
		if isTableRequest(r) {
			encodeTable(w, crdsToTable([]map[string]interface{}{item}, s.rv()))
			return
		}
		if md, ok := item["metadata"].(map[string]interface{}); ok {
			md["resourceVersion"] = s.rv()
		}
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(item)
		return
	}
	s.respondStatus(w, http.StatusNotFound, "NotFound", "customresourcedefinitions %q not found", name)
}

// --- CustomResourceDefinition table ---

var crdColumns = []columnDef{
	{Name: "Name", Type: "string", Format: "name", Description: "Custom resource definition name", Priority: 0},
	{Name: "Created At", Type: "string", Description: "Time since creation", Priority: 0},
}

func crdsToTable(items []map[string]interface{}, rv string) *table {
	t := newTable(rv, crdColumns)
	for _, item := range items {
		meta := crdMetadata(item)
		t.Rows = append(t.Rows, tableRow{
			Cells:  []interface{}{meta.Name, age(meta.CreationTimestamp.Time)},
			Object: partialMeta{Kind: "CustomResourceDefinition", APIVersion: "apiextensions.k8s.io/v1", Metadata: meta},
		})
	}
	return t
}

func crdMetadata(item map[string]interface{}) metav1.ObjectMeta {
	var meta metav1.ObjectMeta
	md, _ := item["metadata"].(map[string]interface{})
	if name, ok := md["name"].(string); ok {
		meta.Name = name
	}
	if stamp, ok := md["creationTimestamp"].(string); ok && stamp != "" {
		if parsed, err := time.Parse(time.RFC3339, stamp); err == nil {
			meta.CreationTimestamp = metav1.NewTime(parsed)
		}
	}
	return meta
}
